INSERT INTO products (title_ar, description_ar, price, category_ar, image_url, rating, min_vip_level, is_available) VALUES
('عطر العود الملكي الفاخر - 100 مل', 'عطر عربي ملكي فواح بتركيبة دهن العود المعتق مع نفحات العنبر وخشب الصندل.', 85.00, 'عطور ومستحضرات فاخرة', 'https://images.unsplash.com/photo-1547887537-6158d64c35b3?w=600&auto=format&fit=crop&q=80', 4.9, 1, true),
('ساعة ذكية فاخرة إصدار التيتانيوم', 'ساعة رياضية ذكية متطورة مع شاشة AMOLED ومستشعر قياس المؤشرات الحيوية.', 140.00, 'أجهزة إلكترونية ذكية', 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=600&auto=format&fit=crop&q=80', 4.8, 1, true),
('سماعات رأس لاسلكية احترافية عازلة للضوضاء', 'تقنية عزل الضوضاء النشطة مع صوت عالي الدقة وبطارية تدوم حتى 40 ساعة متواصلة.', 125.00, 'صوتيات وتقنيات', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=600&auto=format&fit=crop&q=80', 4.9, 1, true),
('كاميرا تصوير بدقة 4K فائقة الوضوح', 'مستشعر تصوير سينمائي مع عدسة بصرية متطورة ومثبت حركة خماسي المحاور.', 380.00, 'إلكترونيات وتصوير', 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?w=600&auto=format&fit=crop&q=80', 5.0, 2, true),
('حقيبة جلدية إيطالية أصلية فاخرة', 'مصنوعة يدوياً من أجود أنواع الجلود الإيطالية الطبيعية المقاومة للخدوش.', 260.00, 'أزياء واكسسوارات', 'https://images.unsplash.com/photo-1548036328-c9fa89d128fa?w=600&auto=format&fit=crop&q=80', 4.8, 2, true),
('نظارات شمسية كلاسيكية مطلية بالذهب', 'إطار كلاسيكي فاخر بعدسات استقطاب لحماية العين الكاملة من الأشعة فوق البنفسجية.', 195.00, 'أزياء راقية', 'https://images.unsplash.com/photo-1511499767150-a48a237f0083?w=600&auto=format&fit=crop&q=80', 4.7, 2, true),
('حاسوب لوحي عالي الأداء مع قلم ذكي', 'شاشة فائقة الاستجابة بتردد 120 هرتز ومعالج ثماني النواة للأعمال الاحترافية.', 720.00, 'كمبيوتر وأجهزة ذكية', 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?w=600&auto=format&fit=crop&q=80', 4.9, 3, true),
('مجموعة العناية بالبشرة السويسرية الفاخرة', 'خلاصة الخلايا الجذعية النباتية السويسرية لإعادة نضارة البشرة ومقاومة علامات التقدم.', 420.00, 'مستحضرات عناية وتجميل', 'https://images.unsplash.com/photo-1571781926291-c477ebfd024b?w=600&auto=format&fit=crop&q=80', 4.9, 3, true),
('ماكينة قهوة إسبريسو إيطالية احترافية', 'ضغط بخار 19 بار ومطحنة حبوب سيراميكية مدمجة للحصول على قهوة نقية وغنية.', 890.00, 'أجهزة منزلية راقية', 'https://images.unsplash.com/photo-1517668808822-9ebb02f2a0e6?w=600&auto=format&fit=crop&q=80', 4.9, 3, true),
('طقم مجوهرات وسوار مرصع بالزركون الماسي', 'تصميم ملكي راق مطلي بالروديوم والذهب الأبيض عيار 18 قيراط للمناسبات الخاصة.', 1850.00, 'مجوهرات وألماس', 'https://images.unsplash.com/photo-1599643478518-a784e5dc4c8f?w=600&auto=format&fit=crop&q=80', 5.0, 4, true),
('شاشة سينمائية منحنية فائقة الدقة OLED 49 بوصة', 'تجربة بصرية مذهلة للأعمال الجرافيكية والترفيه المنزلي مع إضاءة RGB ذكية.', 1650.00, 'شاشات وتقنيات', 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?w=600&auto=format&fit=crop&q=80', 5.0, 4, true),
('طائرة مسيرة درون احترافية مع نظام تتبع ذكي', 'كاميرا تصوير جوي 4K مع نظام استشعار العقبات ثلاثي الأبعاد ومدى تحليق 10 كم.', 2200.00, 'تكنولوجيا ومغامرات', 'https://images.unsplash.com/photo-1508614589041-895b88991e3e?w=600&auto=format&fit=crop&q=80', 5.0, 4, true);
